{
  "sop_id": "SOP-016",
  "title": "Employee Expense Claim Approval",
  "steps": [
    {
      "step_id": "S1",
      "name": "Create ticket and assign to self",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Check policy limits",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Match receipts",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Compute reimbursable amount and submit",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "A1",
      "name": "Incharge approval",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "R1",
      "name": "Correct and resubmit on rejection",
      "role": "Executor",
      "type": "rework"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    },
    {
      "stage": "Lead",
      "condition": "exceptions only"
    }
  ],
  "dependencies": [],
  "rework_reasons": [
    "Amount mismatch",
    "Wrong quantity",
    "Incorrect category",
    "Required document missing"
  ],
  "first_pass_yield_target": 0.95
}
